public class RowMapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.List<Row> sample() {
        java.util.List<Row> rows = new java.util.ArrayList<>();
        rows.add(new Row().put("name", "Ada").put("age", 36));
        rows.add(new Row().put("name", null).put("age", 5));
        rows.add(new Row().put("name", "Bo").put("age", 4));
        return rows;
    }

    public static void main(String[] args) {
        try {
            check("namesOf skips null names",
                  "[Ada, Bo]",
                  String.valueOf(RowMapper.namesOf(sample())));
            check("totalAge sums all ages",
                  45,
                  RowMapper.totalAge(sample()));

            java.util.List<Row> empty = new java.util.ArrayList<>();
            check("namesOf empty list", "[]", String.valueOf(RowMapper.namesOf(empty)));
            check("totalAge empty list", 0, RowMapper.totalAge(empty));

            java.util.List<Row> missing = new java.util.ArrayList<>();
            missing.add(new Row().put("name", "Cy"));
            missing.add(new Row().put("age", 10));
            check("namesOf when age column absent", "[Cy]", String.valueOf(RowMapper.namesOf(missing)));
            check("totalAge when name column absent", 10, RowMapper.totalAge(missing));

            java.util.List<Row> one = new java.util.ArrayList<>();
            one.add(new Row().put("name", "Zed").put("age", 0));
            check("namesOf single row", "[Zed]", String.valueOf(RowMapper.namesOf(one)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

