/**
 * Provided -- do not edit.
 *
 * Row stands in for one row of a query result: a small map from column
 * name to value. get returns null when the column is missing or NULL.
 */
class Row {
    private final java.util.Map<String, Object> values = new java.util.LinkedHashMap<>();

    Row put(String column, Object value) {
        values.put(column, value);
        return this;
    }

    Object get(String column) {
        return values.get(column);
    }
}

public class RowMapper {

    public static java.util.List<String> namesOf(java.util.List<Row> rows) {
        java.util.List<String> names = new java.util.ArrayList<>();
        for (Row row : rows) {
            Object name = row.get("name");
            if (name != null) {
                names.add((String) name);
            }
        }
        return names;
    }

    public static int totalAge(java.util.List<Row> rows) {
        int total = 0;
        for (Row row : rows) {
            Object age = row.get("age");
            if (age != null) {
                total += (Integer) age;
            }
        }
        return total;
    }
}
